values
  ('recipe-001', null::uuid, 'published'::public.recipe_visibility, 'maple-cinnamon-oatmeal', 'Maple Cinnamon Oatmeal', 'Creamy stovetop oats lightly sweetened with maple and warmed with cinnamon.', 2, 12, array['breakfast']::text[], array['American']::text[], array['vegetarian']::text[], array['Bring the milk to a gentle simmer, then stir in the oats and salt.', 'Cook until the oats are creamy, then fold in the maple syrup and cinnamon before serving.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-002', null::uuid, 'published'::public.recipe_visibility, 'banana-peanut-butter-oats', 'Banana Peanut Butter Oats', 'A filling bowl of soft oats with mashed banana and a savory-sweet peanut swirl.', 2, 12, array['breakfast']::text[], array['American']::text[], array['vegetarian']::text[], array['Simmer the oats, milk, and salt until the oats soften and the mixture thickens.', 'Mash the banana into the oats, divide between bowls, and swirl peanut butter through each portion.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-003', null::uuid, 'published'::public.recipe_visibility, 'berry-yogurt-crunch-bowls', 'Berry Yogurt Crunch Bowls', 'Cool yogurt bowls layered with juicy berries, toasted-tasting oats, and honey.', 2, 5, array['breakfast', 'snack']::text[], array['American']::text[], array['vegetarian']::text[], array['Spoon the yogurt into two bowls and scatter the berries evenly over the top.', 'Finish each bowl with the oats and a thin ribbon of honey.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-004', null::uuid, 'published'::public.recipe_visibility, 'spinach-tomato-scrambled-eggs', 'Spinach Tomato Scrambled Eggs', 'Soft scrambled eggs folded with tender spinach and bright fresh tomato.', 2, 15, array['breakfast', 'lunch']::text[], array['American']::text[], array['vegetarian']::text[], array['Melt the butter in a skillet and wilt the spinach with the tomato for two minutes.', 'Beat the eggs with the salt and black pepper, pour them into the skillet, and stir gently until softly set.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-005', null::uuid, 'published'::public.recipe_visibility, 'spinach-cheddar-omelet', 'Spinach Cheddar Omelet', 'A folded breakfast omelet with leafy spinach and melted cheddar cheese.', 1, 12, array['breakfast', 'lunch']::text[], array['American']::text[], array['vegetarian']::text[], array['Melt the butter, wilt the spinach, and transfer the spinach to a small plate.', 'Whisk the eggs with salt, cook until nearly set, add the spinach and cheddar cheese to one side, then fold the omelet closed.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-006', null::uuid, 'published'::public.recipe_visibility, 'egg-and-salsa-breakfast-quesadilla', 'Egg and Salsa Breakfast Quesadilla', 'Crisp tortillas hold fluffy eggs, cheddar, and a lively spoonful of salsa.', 2, 18, array['breakfast', 'lunch']::text[], array['Mexican-inspired']::text[], array['vegetarian']::text[], array['Melt the butter and scramble the eggs just until set, then move the eggs to a plate.', 'Fill the tortillas with the eggs, cheddar cheese, and salsa, then brown both sides in the skillet and cut into wedges.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-007', null::uuid, 'published'::public.recipe_visibility, 'cinnamon-maple-french-toast', 'Cinnamon Maple French Toast', 'Golden slices of custardy bread seasoned with cinnamon and finished with maple syrup.', 2, 20, array['breakfast']::text[], array['American']::text[], array['vegetarian']::text[], array['Whisk the eggs, milk, and cinnamon in a shallow dish, then soak each piece of bread briefly on both sides.', 'Melt the butter in a skillet, cook the bread until browned on both sides, and serve with maple syrup.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-008', null::uuid, 'published'::public.recipe_visibility, 'banana-oat-blender-pancakes', 'Banana Oat Blender Pancakes', 'Tender little pancakes built from oats and banana with no separate flour mixture.', 2, 20, array['breakfast']::text[], array['American']::text[], array['vegetarian']::text[], array['Blend the banana, oats, eggs, milk, and baking powder until a thick, mostly smooth batter forms.', 'Brush a skillet with vegetable oil and cook small pancakes until bubbles appear, then flip and brown the second side.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-009', null::uuid, 'published'::public.recipe_visibility, 'apple-brown-sugar-oats', 'Apple Brown Sugar Oats', 'Warm oats simmered with diced apple and a modest spoonful of brown sugar.', 2, 15, array['breakfast']::text[], array['American']::text[], array['vegetarian']::text[], array['Simmer the apple in the milk for three minutes, then add the oats and salt.', 'Cook until the oats soften, then stir in the brown sugar and cinnamon.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-010', null::uuid, 'published'::public.recipe_visibility, 'paprika-potato-egg-skillet', 'Paprika Potato Egg Skillet', 'Crisp-edged potatoes and onion topped with eggs for a sturdy one-pan breakfast.', 2, 30, array['breakfast', 'dinner']::text[], array['American']::text[], array['vegetarian']::text[], array['Heat the olive oil and cook the potato with the onion, paprika, salt, and black pepper until browned and tender.', 'Make four spaces among the potatoes, crack in the eggs, cover, and cook until the egg whites set.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-011', null::uuid, 'published'::public.recipe_visibility, 'lemon-chickpea-chopped-salad', 'Lemon Chickpea Chopped Salad', 'A crisp no-cook salad of chickpeas, cucumber, tomato, and sharp lemon dressing.', 3, 15, array['lunch', 'dinner']::text[], array['Mediterranean-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Combine the chickpeas, cucumber, tomato, and onion in a wide bowl.', 'Juice the lemon over the salad, add the olive oil and salt, and toss thoroughly.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-012', null::uuid, 'published'::public.recipe_visibility, 'crunchy-tuna-salad-sandwiches', 'Crunchy Tuna Salad Sandwiches', 'Classic tuna salad gains extra crunch from celery and a gentle mustard bite.', 2, 10, array['lunch']::text[], array['American']::text[], array[]::text[], array['Mix the tuna with the mayonnaise, mustard, celery, and black pepper until evenly dressed.', 'Divide the tuna mixture between two pieces of bread and close each sandwich with the remaining bread.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-013', null::uuid, 'published'::public.recipe_visibility, 'mustardy-egg-salad-sandwiches', 'Mustardy Egg Salad Sandwiches', 'Chopped eggs in a tangy, creamy dressing make a quick and familiar lunch.', 2, 20, array['lunch']::text[], array['American']::text[], array['vegetarian']::text[], array['Chop the eggs and fold them together with the mayonnaise, mustard, salt, and black pepper.', 'Spread the egg salad over two pieces of bread and top with the remaining bread.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-014', null::uuid, 'published'::public.recipe_visibility, 'avocado-chickpea-toast', 'Avocado Chickpea Toast', 'Creamy avocado and chickpeas make a substantial, lemony topping for crisp bread.', 2, 12, array['breakfast', 'lunch']::text[], array['American']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Mash the avocado and chickpeas with the lemon, salt, and black pepper, leaving some chickpeas chunky.', 'Toast the bread until crisp and spoon the avocado-chickpea mixture over each piece.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-015', null::uuid, 'published'::public.recipe_visibility, 'tomato-cucumber-chickpea-salad', 'Tomato Cucumber Chickpea Salad', 'A simple vinegar-dressed combination of juicy tomato, cucumber, and chickpeas.', 4, 15, array['lunch', 'side']::text[], array['Mediterranean-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Place the tomato, cucumber, and chickpeas in a serving bowl.', 'Whisk the vinegar, olive oil, oregano, and salt, pour the dressing over the salad, and toss.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-016', null::uuid, 'published'::public.recipe_visibility, 'kale-apple-cheddar-salad', 'Kale Apple Cheddar Salad', 'Tart apple and savory cheddar soften the edges of a massaged kale salad.', 3, 15, array['lunch', 'side']::text[], array['American']::text[], array['vegetarian']::text[], array['Massage the kale with the olive oil and salt until the leaves become darker and more tender.', 'Whisk the vinegar with the honey, toss it with the kale, and fold in the apple and cheddar cheese.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-017', null::uuid, 'published'::public.recipe_visibility, 'lime-black-bean-corn-salad', 'Lime Black Bean Corn Salad', 'A bright pantry-friendly salad with black beans, sweet corn, tomato, and lime.', 4, 15, array['lunch', 'side']::text[], array['Mexican-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Combine the black beans, corn, and tomato in a large bowl.', 'Juice the lime over the bowl, add the olive oil, cumin, and salt, and toss until evenly coated.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-018', null::uuid, 'published'::public.recipe_visibility, 'lemon-tuna-rice-salad', 'Lemon Tuna Rice Salad', 'Chilled rice, tuna, and cucumber come together in a light lemon-mayonnaise dressing.', 3, 15, array['lunch']::text[], array['American']::text[], array[]::text[], array['Fluff the rice in a bowl, then fold in the tuna and cucumber.', 'Stir the mayonnaise with juice from the lemon and the black pepper, then toss the dressing through the rice salad.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-019', null::uuid, 'published'::public.recipe_visibility, 'warm-lentil-spinach-salad', 'Warm Lentil Spinach Salad', 'Warm lentils gently wilt spinach beneath a sharp onion and vinegar dressing.', 3, 20, array['lunch', 'dinner']::text[], array['European-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Warm the lentils with the onion and olive oil until the onion softens slightly.', 'Whisk the vinegar, mustard, and salt, pour it over the lentils, then toss the warm mixture with the spinach.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-020', null::uuid, 'published'::public.recipe_visibility, 'skillet-cheddar-tomato-sandwiches', 'Skillet Cheddar Tomato Sandwiches', 'Buttery grilled sandwiches pair melted cheddar with slices of fresh tomato.', 2, 15, array['lunch', 'dinner']::text[], array['American']::text[], array['vegetarian']::text[], array['Layer the cheddar cheese and tomato between pairs of bread, then spread butter over the outer bread surfaces.', 'Cook the sandwiches in a covered skillet until the bread is browned and the cheddar cheese has melted.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-021', null::uuid, 'published'::public.recipe_visibility, 'tomato-basil-pantry-soup', 'Tomato Basil Pantry Soup', 'A smooth, weeknight tomato soup rounded out with onion, garlic, and basil.', 4, 30, array['lunch', 'dinner']::text[], array['Italian-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Warm the olive oil and cook the onion until translucent, then add the garlic for one minute.', 'Add the canned tomatoes, vegetable broth, basil, and salt, simmer for twenty minutes, then blend to the desired texture.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-022', null::uuid, 'published'::public.recipe_visibility, 'lentil-carrot-soup', 'Lentil Carrot Soup', 'Earthy lentils simmer with carrots, celery, tomato, and cumin in a hearty broth.', 6, 50, array['lunch', 'dinner']::text[], array['Mediterranean-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Heat the olive oil and soften the onion, carrot, and celery, then stir in the cumin.', 'Add the lentils, canned tomatoes, vegetable broth, and salt, then simmer until the lentils are tender.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-023', null::uuid, 'published'::public.recipe_visibility, 'smoky-black-bean-soup', 'Smoky Black Bean Soup', 'Black beans become a thick, smoky soup with tomato, cumin, and chili powder.', 4, 30, array['lunch', 'dinner']::text[], array['Mexican-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Cook the onion in the olive oil until soft, then stir in the cumin and chili powder.', 'Add the black beans, canned tomatoes, vegetable broth, and salt, simmer for twenty minutes, and mash some beans to thicken the soup.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-024', null::uuid, 'published'::public.recipe_visibility, 'thyme-chicken-rice-soup', 'Thyme Chicken Rice Soup', 'A straightforward chicken and rice soup filled with carrots, celery, onion, and thyme.', 6, 45, array['lunch', 'dinner']::text[], array['American']::text[], array[]::text[], array['Warm the olive oil and cook the chicken breast until opaque, then add the onion, carrot, and celery.', 'Pour in the chicken broth, stir in the rice, thyme, and salt, and simmer until the rice and chicken breast are fully cooked.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-025', null::uuid, 'published'::public.recipe_visibility, 'broccoli-cheddar-soup', 'Broccoli Cheddar Soup', 'A cozy broccoli soup thickened lightly with flour and finished with cheddar cheese.', 4, 35, array['lunch', 'dinner']::text[], array['American']::text[], array['vegetarian']::text[], array['Melt the butter, soften the onion, stir in the flour, then gradually whisk in the vegetable broth and milk.', 'Add the broccoli, salt, and black pepper, simmer until tender, then remove from heat and stir in the cheddar cheese.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-026', null::uuid, 'published'::public.recipe_visibility, 'white-bean-cabbage-soup', 'White Bean Cabbage Soup', 'Tender cabbage and white beans turn a basic broth into a satisfying vegetable soup.', 6, 40, array['lunch', 'dinner']::text[], array['European-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Heat the olive oil and soften the onion and carrot, then add the cabbage and cook until it begins to collapse.', 'Stir in the white beans, vegetable broth, thyme, and salt, then simmer until the cabbage is tender.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-027', null::uuid, 'published'::public.recipe_visibility, 'paprika-chickpea-tomato-stew', 'Paprika Chickpea Tomato Stew', 'Chickpeas simmer in a warmly spiced tomato base for a fast pantry supper.', 4, 30, array['lunch', 'dinner']::text[], array['Mediterranean-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Cook the onion in the olive oil until soft, then add the garlic, cumin, and paprika.', 'Stir in the chickpeas, canned tomatoes, and salt, then simmer until the mixture becomes thick and glossy.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-028', null::uuid, 'published'::public.recipe_visibility, 'mushroom-barley-soup', 'Mushroom Barley Soup', 'Chewy barley and mushrooms simmer with carrots and thyme in a savory broth.', 6, 60, array['lunch', 'dinner']::text[], array['European-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Brown the mushrooms in the olive oil, then add the onion and carrot and cook until softened.', 'Add the barley, vegetable broth, thyme, and salt, then simmer until the barley is tender and plump.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-029', null::uuid, 'published'::public.recipe_visibility, 'coconut-sweet-potato-lentil-soup', 'Coconut Sweet Potato Lentil Soup', 'Red lentils and sweet potato cook into a silky coconut curry soup.', 6, 45, array['lunch', 'dinner']::text[], array['South Asian-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Cook the onion in the vegetable oil until soft, then stir in the curry powder.', 'Add the sweet potato, lentils, vegetable broth, coconut milk, and salt, then simmer until the sweet potato and lentils are very tender.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-030', null::uuid, 'published'::public.recipe_visibility, 'corn-potato-chowder', 'Corn Potato Chowder', 'Sweet corn and diced potatoes make a creamy, lightly thickened stovetop chowder.', 6, 40, array['lunch', 'dinner']::text[], array['American']::text[], array['vegetarian']::text[], array['Melt the butter, soften the onion, stir in the flour, then slowly add the vegetable broth and milk.', 'Add the potato, corn, salt, and black pepper, and simmer until the potato is tender and the chowder thickens.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-031', null::uuid, 'published'::public.recipe_visibility, 'simple-marinara-spaghetti', 'Simple Marinara Spaghetti', 'A dependable bowl of spaghetti coated in marinara and finished with parmesan.', 4, 25, array['dinner']::text[], array['Italian-inspired']::text[], array['vegetarian']::text[], array['Bring the water and salt to a boil, cook the pasta until tender, then drain it.', 'Warm the marinara sauce with the olive oil, toss it with the pasta, and finish with parmesan cheese.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-032', null::uuid, 'published'::public.recipe_visibility, 'garlic-butter-parmesan-pasta', 'Garlic Butter Parmesan Pasta', 'Hot pasta turns glossy with garlic butter, parmesan, and cracked black pepper.', 4, 22, array['dinner']::text[], array['Italian-inspired']::text[], array['vegetarian']::text[], array['Boil the water with the salt, cook the pasta until tender, reserve a little water, and drain.', 'Melt the butter with the garlic, toss in the pasta and parmesan cheese with enough reserved water to coat, then add black pepper.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-033', null::uuid, 'published'::public.recipe_visibility, 'spinach-pesto-pasta', 'Spinach Pesto Pasta', 'Pesto-coated pasta gets an extra helping of spinach and a parmesan finish.', 4, 20, array['dinner']::text[], array['Italian-inspired']::text[], array['vegetarian']::text[], array['Boil the water with the salt, cook the pasta until nearly tender, and add the spinach for the final minute before draining.', 'Toss the hot pasta and spinach with the pesto, then scatter parmesan cheese over each portion.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-034', null::uuid, 'published'::public.recipe_visibility, 'creamy-mushroom-pasta', 'Creamy Mushroom Pasta', 'Browned mushrooms and garlic flavor a simple cream sauce for pasta.', 4, 30, array['dinner']::text[], array['Italian-inspired']::text[], array['vegetarian']::text[], array['Boil the water with the salt, cook the pasta until tender, and drain.', 'Brown the mushrooms in the butter, add the garlic and heavy cream, then toss with the pasta and parmesan cheese.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-035', null::uuid, 'published'::public.recipe_visibility, 'tuna-tomato-pasta', 'Tuna Tomato Pasta', 'A pantry pasta with tuna, tomato, onion, and oregano in every forkful.', 4, 28, array['dinner']::text[], array['Mediterranean-inspired']::text[], array[]::text[], array['Boil the water with the salt, cook the pasta until tender, and drain.', 'Soften the onion in the olive oil, add the canned tomatoes, oregano, and tuna, then simmer briefly and toss with the pasta.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-036', null::uuid, 'published'::public.recipe_visibility, 'sausage-bell-pepper-pasta', 'Sausage Bell Pepper Pasta', 'Savory sausage and sweet bell pepper simmer in marinara before meeting pasta.', 5, 35, array['dinner']::text[], array['Italian-American']::text[], array[]::text[], array['Boil the water with the salt, cook the pasta until tender, and drain.', 'Brown the sausage in the olive oil, soften the bell pepper and onion, add the marinara sauce, then toss with the pasta.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-037', null::uuid, 'published'::public.recipe_visibility, 'lemon-broccoli-pasta', 'Lemon Broccoli Pasta', 'Broccoli and pasta share a bright coating of lemon, garlic, olive oil, and parmesan.', 4, 25, array['dinner']::text[], array['Italian-inspired']::text[], array['vegetarian']::text[], array['Boil the water with the salt, add the pasta, and cook the broccoli in the same pot during the final four minutes before draining.', 'Warm the garlic in the olive oil, toss with the pasta and broccoli, then add juice from the lemon and the parmesan cheese.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-038', null::uuid, 'published'::public.recipe_visibility, 'fresh-tomato-zucchini-pasta', 'Fresh Tomato Zucchini Pasta', 'Quick-cooked tomato and zucchini make a light, basil-scented pasta sauce.', 4, 30, array['dinner']::text[], array['Italian-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Boil the water with half the salt, cook the pasta until tender, and drain.', 'Cook the zucchini and garlic in the olive oil, add the tomato, basil, and remaining salt, then toss the quick sauce with the pasta.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-039', null::uuid, 'published'::public.recipe_visibility, 'stovetop-cheddar-macaroni', 'Stovetop Cheddar Macaroni', 'A smooth cheddar sauce coats tender macaroni without requiring the oven.', 5, 28, array['lunch', 'dinner']::text[], array['American']::text[], array['vegetarian']::text[], array['Boil the water with half the salt, cook the pasta until tender, and drain.', 'Melt the butter, whisk in the flour, slowly add the milk, then melt in the cheddar cheese and toss with the pasta and remaining salt.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-040', null::uuid, 'published'::public.recipe_visibility, 'peanut-sesame-noodles', 'Peanut Sesame Noodles', 'Noodles and carrots are tossed in a savory peanut, soy, sesame, and lime sauce.', 4, 22, array['lunch', 'dinner']::text[], array['Asian-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Boil the water, cook the noodles until tender, drain, and rinse briefly.', 'Whisk the peanut butter, soy sauce, sesame oil, and juice from the lime, then toss with the noodles and carrot.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-041', null::uuid, 'published'::public.recipe_visibility, 'black-bean-corn-rice-bowls', 'Black Bean Corn Rice Bowls', 'Warm rice bowls layered with black beans, corn, salsa, avocado, and lime.', 4, 35, array['lunch', 'dinner']::text[], array['Mexican-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Simmer the rice with the water and salt until tender, then let it rest covered for five minutes.', 'Warm the black beans and corn, divide them over the rice, and top each bowl with salsa, avocado, and juice from the lime.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-042', null::uuid, 'published'::public.recipe_visibility, 'chicken-vegetable-fried-rice', 'Chicken Vegetable Fried Rice', 'Cooked rice becomes a fast skillet meal with chicken, eggs, peas, and carrots.', 4, 30, array['dinner']::text[], array['Chinese-inspired']::text[], array[]::text[], array['Heat half the vegetable oil and cook the chicken breast completely, then add the carrot and peas and move everything to one side.', 'Add the remaining vegetable oil, scramble the eggs, then fold in the rice, soy sauce, sesame oil, chicken breast, carrot, and peas until hot.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-043', null::uuid, 'published'::public.recipe_visibility, 'corn-pea-vegetable-fried-rice', 'Corn Pea Vegetable Fried Rice', 'A colorful fried rice with eggs, peas, corn, carrots, soy sauce, and sesame oil.', 4, 22, array['lunch', 'dinner']::text[], array['Chinese-inspired']::text[], array['vegetarian']::text[], array['Heat half the vegetable oil and cook the carrot, peas, and corn until hot, then move the vegetables aside and scramble the eggs.', 'Add the remaining vegetable oil, rice, soy sauce, and sesame oil, and toss with the eggs, carrot, peas, and corn until evenly heated.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-044', null::uuid, 'published'::public.recipe_visibility, 'chickpea-coconut-curry-rice', 'Chickpea Coconut Curry Rice', 'A tomato-coconut chickpea curry served over simple steamed rice.', 5, 40, array['dinner']::text[], array['South Asian-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Simmer the rice with the water and half the salt until tender, then rest it covered.', 'Soften the onion in the vegetable oil, add the curry powder, chickpeas, canned tomatoes, coconut milk, and remaining salt, and simmer before serving over the rice.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-045', null::uuid, 'published'::public.recipe_visibility, 'tofu-broccoli-rice-plates', 'Tofu Broccoli Rice Plates', 'Crisp tofu and broccoli are glazed with garlic, soy, and sesame over rice.', 4, 40, array['dinner']::text[], array['Asian-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Simmer the rice with the water until tender, while browning the tofu in the vegetable oil.', 'Add the broccoli and garlic to the tofu, cover until the broccoli is tender, then toss with soy sauce and sesame oil and serve over the rice.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-046', null::uuid, 'published'::public.recipe_visibility, 'lime-shrimp-corn-rice-bowls', 'Lime Shrimp Corn Rice Bowls', 'Cumin shrimp, sweet corn, and bell pepper sit over rice with fresh lime.', 4, 35, array['dinner']::text[], array['Mexican-inspired']::text[], array['dairy-free']::text[], array['Simmer the rice with the water and half the salt until tender, then rest it covered.', 'Cook the bell pepper and corn in the olive oil, add the shrimp, cumin, and remaining salt until the shrimp is opaque, then finish with the lime and serve over rice.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-047', null::uuid, 'published'::public.recipe_visibility, 'quinoa-chickpea-lemon-bowls', 'Quinoa Chickpea Lemon Bowls', 'Fluffy quinoa supports chickpeas, cucumber, tomato, and a lemon-olive oil dressing.', 4, 30, array['lunch', 'dinner']::text[], array['Mediterranean-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Simmer the quinoa with the water and half the salt until the grains open, then cool for five minutes.', 'Divide the quinoa into bowls, add the chickpeas, cucumber, and tomato, then dress with the lemon, olive oil, and remaining salt.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-048', null::uuid, 'published'::public.recipe_visibility, 'cumin-vegetable-couscous', 'Cumin Vegetable Couscous', 'Quick couscous is folded with sautéed zucchini, bell pepper, chickpeas, and cumin.', 4, 28, array['lunch', 'dinner']::text[], array['North African-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Bring the water and half the salt to a boil, stir in the couscous, cover, remove from heat, and let it stand.', 'Cook the zucchini and bell pepper in the olive oil with the cumin, add the chickpeas and remaining salt, then fold everything into the couscous.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-049', null::uuid, 'published'::public.recipe_visibility, 'lentil-onion-rice-pilaf', 'Lentil Onion Rice Pilaf', 'Lentils and rice simmer together beneath deeply softened cumin-scented onion.', 6, 50, array['lunch', 'dinner']::text[], array['Middle Eastern-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Cook the onion slowly in the olive oil until deeply golden, then reserve half and stir the cumin into the rest.', 'Add the rice, lentils, vegetable broth, and salt, simmer until tender, and finish the pilaf with the reserved onion.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-050', null::uuid, 'published'::public.recipe_visibility, 'stuffed-bell-pepper-skillet', 'Stuffed Bell Pepper Skillet', 'The flavors of stuffed peppers become a one-pan beef, rice, tomato, and cheddar meal.', 5, 45, array['dinner']::text[], array['American']::text[], array[]::text[], array['Brown the ground beef in the olive oil, then add the onion, bell pepper, chili powder, and salt.', 'Stir in the rice, canned tomatoes, and beef broth, cover until the rice is tender, then melt the cheddar cheese over the skillet.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-051', null::uuid, 'published'::public.recipe_visibility, 'paprika-chicken-thighs-and-potatoes', 'Paprika Chicken Thighs and Potatoes', 'A sheet-pan dinner of paprika chicken thighs, potatoes, carrots, and onion.', 4, 50, array['dinner']::text[], array['American']::text[], array['dairy-free']::text[], array['Toss the potato, carrot, and onion with the olive oil, paprika, thyme, salt, and black pepper on a sheet pan.', 'Nestle the chicken thighs among the vegetables and roast until the vegetables are tender and the chicken thighs are fully cooked.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-052', null::uuid, 'published'::public.recipe_visibility, 'lemon-garlic-chicken-and-broccoli', 'Lemon Garlic Chicken and Broccoli', 'A bright skillet of chicken breast and broccoli with lemon and plenty of garlic.', 4, 30, array['dinner']::text[], array['American']::text[], array['dairy-free']::text[], array['Season the chicken breast with the salt and black pepper, then cook it completely in the olive oil and move it to a plate.', 'Cook the broccoli and garlic in the skillet, return the chicken breast, and finish everything with juice from the lemon.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-053', null::uuid, 'published'::public.recipe_visibility, 'lime-chicken-fajitas', 'Lime Chicken Fajitas', 'Sizzling chicken breast, bell peppers, and onion are tucked into warm tortillas.', 4, 35, array['dinner']::text[], array['Mexican-inspired']::text[], array['dairy-free']::text[], array['Cook the bell pepper and onion in half the vegetable oil until browned, then transfer them to a plate.', 'Cook the chicken breast completely in the remaining vegetable oil with the cumin, chili powder, and salt, return the vegetables, add the lime, and serve in tortillas.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-054', null::uuid, 'published'::public.recipe_visibility, 'tomato-spinach-chicken-thigh-skillet', 'Tomato Spinach Chicken Thigh Skillet', 'Chicken thighs simmer in an oregano tomato sauce with a final handful of spinach.', 4, 40, array['dinner']::text[], array['Mediterranean-inspired']::text[], array['dairy-free']::text[], array['Brown the chicken thighs in the olive oil, then add the onion and garlic around them.', 'Add the canned tomatoes, oregano, and salt, simmer until the chicken thighs are fully cooked, then wilt in the spinach.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-055', null::uuid, 'published'::public.recipe_visibility, 'skillet-beef-tacos', 'Skillet Beef Tacos', 'Seasoned ground beef fills tortillas with salsa, cheddar, and crisp onion.', 4, 25, array['dinner']::text[], array['Mexican-inspired']::text[], array[]::text[], array['Brown the ground beef in the vegetable oil with the cumin, chili powder, and salt until completely cooked.', 'Fill the tortillas with the ground beef, onion, salsa, and cheddar cheese.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-056', null::uuid, 'published'::public.recipe_visibility, 'beef-potato-pea-skillet', 'Beef Potato Pea Skillet', 'Ground beef, browned potatoes, and peas cook together in a paprika broth.', 5, 40, array['dinner']::text[], array['American']::text[], array['dairy-free']::text[], array['Brown the potato in the olive oil, then add the onion and ground beef and cook the ground beef completely.', 'Stir in the peas, beef broth, paprika, salt, and black pepper, cover, and cook until the potato is tender.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-057', null::uuid, 'published'::public.recipe_visibility, 'apple-onion-pork-chops', 'Apple Onion Pork Chops', 'Pan-cooked pork chops are paired with soft apples, onion, butter, and thyme.', 4, 35, array['dinner']::text[], array['American']::text[], array[]::text[], array['Season the pork chops with the salt and black pepper, then cook them in half the butter until done and rest them on a plate.', 'Cook the apple and onion in the remaining butter with the thyme until tender, then spoon them over the pork chops.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-058', null::uuid, 'published'::public.recipe_visibility, 'mustard-sausage-cabbage-skillet', 'Mustard Sausage Cabbage Skillet', 'Sausage and cabbage cook down with onion, mustard, and black pepper in one pan.', 4, 35, array['dinner']::text[], array['European-inspired']::text[], array['dairy-free']::text[], array['Brown the sausage in the vegetable oil, then add the onion and cook until soft.', 'Add the cabbage, salt, and black pepper, cover until tender, then stir the mustard through the sausage and cabbage.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-059', null::uuid, 'published'::public.recipe_visibility, 'soy-beef-bell-pepper-rice', 'Soy Beef Bell Pepper Rice', 'Thin beef steak and bell pepper are glazed with garlic and soy sauce over rice.', 4, 35, array['dinner']::text[], array['Asian-inspired']::text[], array['dairy-free']::text[], array['Simmer the rice with the water until tender, while searing the beef steak in half the vegetable oil.', 'Cook the bell pepper, onion, and garlic in the remaining vegetable oil, return the beef steak, add the soy sauce, and serve over the rice.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-060', null::uuid, 'published'::public.recipe_visibility, 'pesto-tomato-chicken-bake', 'Pesto Tomato Chicken Bake', 'Chicken breast bakes beneath pesto, fresh tomato, and a layer of mozzarella.', 4, 40, array['dinner']::text[], array['Italian-inspired']::text[], array[]::text[], array['Coat a baking dish with the olive oil, arrange the chicken breast, season with salt, and spread the pesto over it.', 'Layer the tomato and mozzarella cheese over the chicken breast and bake until the chicken breast is fully cooked and the mozzarella cheese is browned.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-061', null::uuid, 'published'::public.recipe_visibility, 'lemon-garlic-salmon-and-broccoli', 'Lemon Garlic Salmon and Broccoli', 'Salmon and broccoli roast together with lemon, garlic, olive oil, and black pepper.', 4, 30, array['dinner']::text[], array['American']::text[], array['dairy-free']::text[], array['Toss the broccoli with half the olive oil, garlic, salt, and black pepper, then spread it on a sheet pan.', 'Add the salmon, brush it with the remaining olive oil and juice from the lemon, and roast until the broccoli is tender and the salmon is cooked through.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-062', null::uuid, 'published'::public.recipe_visibility, 'paprika-salmon-sweet-potato-plates', 'Paprika Salmon Sweet Potato Plates', 'Paprika-seasoned salmon roasts beside sweet potatoes and is served over spinach.', 4, 45, array['dinner']::text[], array['American']::text[], array['dairy-free']::text[], array['Toss the sweet potato with two tablespoons olive oil, half the paprika, and half the salt, then roast until nearly tender.', 'Season the salmon with the remaining olive oil, paprika, and salt, roast until cooked through, and serve the salmon and sweet potato over the spinach.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-063', null::uuid, 'published'::public.recipe_visibility, 'lemon-paprika-shrimp-pasta', 'Lemon Paprika Shrimp Pasta', 'Shrimp and pasta are coated in a quick garlic butter sauce with lemon and paprika.', 4, 25, array['dinner']::text[], array['Mediterranean-inspired']::text[], array[]::text[], array['Boil the water with the salt, cook the pasta until tender, reserve a little water, and drain.', 'Melt the butter with the garlic and paprika, cook the shrimp until opaque, then toss with the pasta, juice from the lemon, and enough reserved water to coat.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-064', null::uuid, 'published'::public.recipe_visibility, 'mustard-tuna-potato-patties', 'Mustard Tuna Potato Patties', 'Mashed potato binds tuna, egg, onion, and mustard into crisp skillet patties.', 4, 35, array['lunch', 'dinner']::text[], array['American']::text[], array['dairy-free']::text[], array['Cook the potato until tender, mash it, then mix in the tuna, egg, onion, mustard, salt, and black pepper and shape into patties.', 'Heat the vegetable oil and cook the tuna-potato patties until firm and browned on both sides.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-065', null::uuid, 'published'::public.recipe_visibility, 'sesame-tofu-cabbage-stir-fry', 'Sesame Tofu Cabbage Stir-Fry', 'Tofu, cabbage, and carrots are tossed with garlic, soy sauce, and sesame oil.', 4, 30, array['dinner']::text[], array['Asian-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Brown the tofu in the vegetable oil, then transfer the tofu to a plate.', 'Stir-fry the cabbage, carrot, and garlic, return the tofu, and toss everything with the soy sauce and sesame oil.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-066', null::uuid, 'published'::public.recipe_visibility, 'avocado-black-bean-tacos', 'Avocado Black Bean Tacos', 'Cumin black beans fill tortillas with crunchy cabbage, salsa, avocado, and lime.', 4, 25, array['lunch', 'dinner']::text[], array['Mexican-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Warm the black beans in the olive oil with the cumin and salt, lightly mashing a few beans.', 'Fill the tortillas with the black beans, cabbage, salsa, and avocado, then finish with juice from the lime.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-067', null::uuid, 'published'::public.recipe_visibility, 'lentil-sloppy-sandwiches', 'Lentil Sloppy Sandwiches', 'Cooked lentils simmer in a tangy tomato and bell pepper filling for soft sandwiches.', 4, 30, array['lunch', 'dinner']::text[], array['American']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Cook the onion and bell pepper in the olive oil, then stir in the tomato paste, mustard, chili powder, and salt.', 'Add the lentils and canned tomatoes, simmer until thick, then spoon the lentil filling between pairs of bread.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-068', null::uuid, 'published'::public.recipe_visibility, 'cauliflower-chickpea-coconut-curry', 'Cauliflower Chickpea Coconut Curry', 'Cauliflower and chickpeas simmer in a tomato-coconut curry that needs only one pot.', 5, 40, array['dinner']::text[], array['South Asian-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Soften the onion in the vegetable oil, then stir in the curry powder.', 'Add the cauliflower, chickpeas, coconut milk, canned tomatoes, and salt, then simmer until the cauliflower is tender.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-069', null::uuid, 'published'::public.recipe_visibility, 'zucchini-white-bean-spinach-skillet', 'Zucchini White Bean Spinach Skillet', 'Zucchini, tomato, white beans, and spinach form a quick oregano-scented skillet meal.', 4, 28, array['lunch', 'dinner']::text[], array['Mediterranean-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Brown the zucchini in the olive oil, then add the garlic, tomato, oregano, and salt.', 'Fold in the white beans and spinach and cook until the white beans are hot and the spinach has wilted.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-070', null::uuid, 'published'::public.recipe_visibility, 'black-bean-corn-stuffed-sweet-potatoes', 'Black Bean Corn Stuffed Sweet Potatoes', 'Baked sweet potatoes are split and piled with black beans, corn, salsa, and cheddar.', 4, 55, array['lunch', 'dinner']::text[], array['Mexican-inspired']::text[], array['vegetarian']::text[], array['Bake the sweet potatoes until soft, then split them and season their centers with the salt.', 'Warm the black beans and corn, spoon them into the sweet potatoes with the salsa, add the cheddar cheese, and bake until melted.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-071', null::uuid, 'published'::public.recipe_visibility, 'lentil-spinach-loaded-potatoes', 'Lentil Spinach Loaded Potatoes', 'Baked potatoes hold warm lentils, wilted spinach, cheddar, and a spoonful of yogurt.', 4, 60, array['lunch', 'dinner']::text[], array['American']::text[], array['vegetarian']::text[], array['Bake the potatoes until tender, while warming the lentils and wilting the spinach in the olive oil with the salt and black pepper.', 'Split the potatoes, add the lentils and spinach, melt the cheddar cheese over the tops, and finish with the yogurt.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-072', null::uuid, 'published'::public.recipe_visibility, 'banana-oat-breakfast-bites', 'Banana Oat Breakfast Bites', 'Soft baked oat bites use banana, peanut butter, cinnamon, and honey for flavor.', 6, 28, array['breakfast', 'snack']::text[], array['American']::text[], array['vegetarian']::text[], array['Mash the banana, then mix it thoroughly with the oats, peanut butter, honey, cinnamon, and salt.', 'Scoop the oat mixture onto a lined pan, flatten each bite slightly, and bake until set at the edges.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-073', null::uuid, 'published'::public.recipe_visibility, 'brown-sugar-apple-crisp', 'Brown Sugar Apple Crisp', 'Sliced apples bake beneath a crumbly oat, flour, butter, and brown sugar topping.', 6, 50, array['dessert']::text[], array['American']::text[], array['vegetarian']::text[], array['Spread the apple in a baking dish and toss it with half the cinnamon and a spoonful of the brown sugar.', 'Rub the oats, flour, butter, salt, remaining cinnamon, and remaining brown sugar into crumbs, scatter over the apple, and bake until bubbling.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-074', null::uuid, 'published'::public.recipe_visibility, 'berry-yogurt-freezer-pops', 'Berry Yogurt Freezer Pops', 'Berries, yogurt, honey, and vanilla freeze into simple homemade pops.', 6, 250, array['dessert', 'snack']::text[], array['American']::text[], array['vegetarian']::text[], array['Blend the berries, yogurt, honey, and vanilla extract until mostly smooth.', 'Pour the berry-yogurt mixture into pop molds and freeze until solid.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-075', null::uuid, 'published'::public.recipe_visibility, 'peanut-butter-oat-energy-bites', 'Peanut Butter Oat Energy Bites', 'No-bake oat bites hold together with peanut butter and honey and a pinch of cinnamon.', 8, 20, array['snack']::text[], array['American']::text[], array['vegetarian']::text[], array['Stir the oats, peanut butter, honey, cinnamon, and salt until no dry oats remain.', 'Chill the oat mixture briefly, then roll it into small, firm bites.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-076', null::uuid, 'published'::public.recipe_visibility, 'apple-cinnamon-baked-oatmeal', 'Apple Cinnamon Baked Oatmeal', 'A sliceable breakfast bake with oats, apple, maple syrup, eggs, and cinnamon.', 6, 45, array['breakfast']::text[], array['American']::text[], array['vegetarian']::text[], array['Coat a baking dish with the butter, then combine the oats, apple, cinnamon, baking powder, and salt in the dish.', 'Whisk the milk, eggs, and maple syrup, pour over the oats and apple, and bake until the center is set.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-077', null::uuid, 'published'::public.recipe_visibility, 'classic-cinnamon-banana-bread', 'Classic Cinnamon Banana Bread', 'A tender banana loaf made with butter, eggs, flour, sugar, and cinnamon.', 10, 75, array['breakfast', 'snack']::text[], array['American']::text[], array['vegetarian']::text[], array['Mash the banana, whisk in the sugar, eggs, and butter, then fold in the flour, baking soda, cinnamon, and salt.', 'Spread the banana batter in a lined loaf pan and bake until the center is set and a tester comes out clean.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-078', null::uuid, 'published'::public.recipe_visibility, 'berry-oat-crumble', 'Berry Oat Crumble', 'Juicy berries bake under a rustic oat, flour, brown sugar, butter, and cinnamon topping.', 6, 45, array['dessert']::text[], array['American']::text[], array['vegetarian']::text[], array['Spread the berries in a baking dish and sprinkle them with one quarter of the brown sugar.', 'Rub the oats, flour, butter, cinnamon, and remaining brown sugar into crumbs, scatter over the berries, and bake until bubbling.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-079', null::uuid, 'published'::public.recipe_visibility, 'maple-cinnamon-baked-apples', 'Maple Cinnamon Baked Apples', 'Whole apples are filled with oats, maple syrup, butter, and cinnamon before baking.', 4, 45, array['dessert', 'snack']::text[], array['American']::text[], array['vegetarian']::text[], array['Core the apples without cutting through the bottoms, then mix the oats, maple syrup, butter, and cinnamon.', 'Pack the oat mixture into the apples and bake until the apples are tender but still hold their shape.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-080', null::uuid, 'published'::public.recipe_visibility, 'cheddar-cornmeal-muffins', 'Cheddar Cornmeal Muffins', 'Savory cornmeal muffins carry cheddar cheese and a tender butter-enriched crumb.', 12, 32, array['breakfast', 'side', 'snack']::text[], array['American']::text[], array['vegetarian']::text[], array['Whisk the cornmeal, flour, baking powder, and salt, then stir in the milk, eggs, butter, and cheddar cheese just until combined.', 'Divide the cornmeal batter among muffin cups and bake until the tops are golden and the centers are set.']::text[], 'Foodtopia', 'Foodtopia Editorial', 'Foodtopia Owner', '2026-08-23'::date, 'reviewed'::public.recipe_review_status, null),
  ('recipe-081', null::uuid, 'published'::public.recipe_visibility, 'simple-chicken-thigh-rice', 'Simple Chicken Thigh Rice', 'A straightforward chicken thigh dinner served with tender rice.', 4, 35, array['dinner']::text[], array['American']::text[], array['dairy-free']::text[], array['Thaw frozen chicken thighs in the refrigerator before starting. Season the chicken thighs with salt and black pepper, then brown them in vegetable oil over medium heat.', 'Cover and continue cooking the chicken thighs until the thickest pieces reach 165°F, while simmering the rice in the water until tender; rest the rice covered for five minutes and serve together.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-082', null::uuid, 'published'::public.recipe_visibility, 'soy-chicken-thigh-rice-bowl', 'Soy Chicken Thigh Rice Bowl', 'Savory chicken thighs and rice finished with soy and sesame.', 4, 35, array['dinner']::text[], array['Asian-inspired']::text[], array['dairy-free']::text[], array['Thaw frozen chicken thighs in the refrigerator before starting, then brown the chicken thighs in vegetable oil and add the soy sauce.', 'Cover and cook the chicken thighs until they reach 165°F. Simmer the rice in the water until tender, finish the chicken with sesame oil, and spoon it over the rice.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-083', null::uuid, 'published'::public.recipe_visibility, 'curry-chicken-thigh-rice', 'Curry Chicken Thigh Rice', 'Warm curry-spiced chicken thighs with a straightforward pot of rice.', 4, 40, array['dinner']::text[], array['South Asian-inspired']::text[], array['dairy-free']::text[], array['Thaw frozen chicken thighs in the refrigerator before starting. Coat the chicken thighs with curry powder and salt, then brown them in vegetable oil.', 'Cover and cook the chicken thighs until they reach 165°F, while simmering the rice in the water until tender; rest the rice covered and serve with the chicken.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-084', null::uuid, 'published'::public.recipe_visibility, 'lemon-chicken-thigh-rice', 'Lemon Chicken Thigh Rice', 'Bright lemon chicken thighs paired with fluffy rice.', 4, 40, array['dinner']::text[], array['Mediterranean-inspired']::text[], array['dairy-free']::text[], array['Thaw frozen chicken thighs in the refrigerator before starting. Season the chicken thighs with salt and brown them in olive oil over medium heat.', 'Cover and continue cooking the chicken thighs until they reach 165°F. Simmer the rice in the water until tender, then squeeze the lemon over the chicken and serve with the rice.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-085', null::uuid, 'published'::public.recipe_visibility, 'salsa-chicken-thigh-rice', 'Salsa Chicken Thigh Rice', 'An easy salsa chicken thigh bowl built on pantry rice.', 4, 35, array['dinner']::text[], array['Mexican-inspired']::text[], array['dairy-free']::text[], array['Thaw frozen chicken thighs in the refrigerator before starting, then brown the chicken thighs in vegetable oil and season with cumin.', 'Add the salsa, cover, and simmer until the chicken thighs reach 165°F. Cook the rice in the water until tender and serve the saucy chicken over it.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-086', null::uuid, 'published'::public.recipe_visibility, 'garlic-chicken-thigh-rice', 'Garlic Chicken Thigh Rice', 'Garlicky chicken thighs and rice for a practical weeknight meal.', 4, 38, array['dinner']::text[], array['Mediterranean-inspired']::text[], array['dairy-free']::text[], array['Thaw frozen chicken thighs in the refrigerator before starting. Brown the chicken thighs in olive oil, then add the garlic and salt around them.', 'Cover and cook until the chicken thighs reach 165°F. Simmer the rice in the water until tender, rest it covered for five minutes, and serve with the garlic chicken.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-087', null::uuid, 'published'::public.recipe_visibility, 'hot-sauce-chicken-thigh-rice', 'Hot Sauce Chicken Thigh Rice', 'Spicy chicken thighs over plain rice with minimal preparation.', 4, 35, array['dinner']::text[], array['American']::text[], array['dairy-free']::text[], array['Thaw frozen chicken thighs in the refrigerator before starting. Season the chicken thighs with salt and brown them in vegetable oil.', 'Cover and continue cooking until the chicken thighs reach 165°F, then coat them with hot sauce. Simmer the rice in the water until tender and serve alongside.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-088', null::uuid, 'published'::public.recipe_visibility, 'honey-chicken-thigh-rice', 'Honey Chicken Thigh Rice', 'A sweet-savory chicken thigh and rice bowl.', 4, 38, array['dinner']::text[], array['Asian-inspired']::text[], array['dairy-free']::text[], array['Thaw frozen chicken thighs in the refrigerator before starting, then brown the chicken thighs in vegetable oil and add the soy sauce.', 'Cover and cook until the chicken thighs reach 165°F. Stir in the honey to glaze the chicken, simmer the rice in the water until tender, and serve together.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-089', null::uuid, 'published'::public.recipe_visibility, 'chicken-thigh-tomato-rice', 'Chicken Thigh Tomato Rice', 'One-pot tomato rice with paprika chicken thighs.', 4, 45, array['dinner']::text[], array['Spanish-inspired']::text[], array['dairy-free']::text[], array['Thaw frozen chicken thighs in the refrigerator before starting. Season the chicken thighs with paprika and salt, then brown them in vegetable oil.', 'Add the canned tomatoes, rice, and water, cover, and simmer until the rice is tender and the chicken thighs reach 165°F; rest for five minutes before serving.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-090', null::uuid, 'published'::public.recipe_visibility, 'chicken-thigh-pea-rice', 'Chicken Thigh Pea Rice', 'A family-style chicken thigh, pea, and rice pot.', 4, 42, array['dinner']::text[], array['European-inspired']::text[], array['dairy-free']::text[], array['Thaw frozen chicken thighs in the refrigerator before starting. Brown the chicken thighs in vegetable oil with thyme and salt.', 'Add the rice and water, cover, and simmer until the chicken thighs reach 165°F and the rice is tender; fold in the peas for the final five minutes.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-091', null::uuid, 'published'::public.recipe_visibility, 'pesto-chicken-breast-rice', 'Pesto Chicken Breast Rice', 'Pesto-coated chicken breast served over rice.', 4, 35, array['dinner']::text[], array['Italian-inspired']::text[], array[]::text[], array['Thaw frozen chicken breast in the refrigerator before starting, then brown the chicken breast in olive oil and coat it with pesto.', 'Cover and cook the chicken breast until it reaches 165°F. Simmer the rice in the water until tender, rest it covered, and serve with the pesto chicken.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-092', null::uuid, 'published'::public.recipe_visibility, 'mustard-chicken-breast-rice', 'Mustard Chicken Breast Rice', 'Tangy mustard chicken breast with simple rice.', 4, 35, array['dinner']::text[], array['French-inspired']::text[], array['dairy-free']::text[], array['Thaw frozen chicken breast in the refrigerator before starting. Season the chicken breast with black pepper and brown it in olive oil.', 'Brush the chicken breast with mustard, cover, and cook until it reaches 165°F. Simmer the rice in the water until tender and serve together.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-093', null::uuid, 'published'::public.recipe_visibility, 'chicken-broccoli-rice-skillet', 'Chicken Broccoli Rice Skillet', 'Chicken, broccoli, and rice in a dependable skillet dinner.', 4, 38, array['dinner']::text[], array['Asian-inspired']::text[], array['dairy-free']::text[], array['Thaw frozen chicken breast in the refrigerator before starting, then brown the chicken breast in vegetable oil and cook until it reaches 165°F.', 'Simmer the rice in the water until tender. Steam the broccoli until crisp-tender, combine it with the chicken and soy sauce, and serve over the rice.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-094', null::uuid, 'published'::public.recipe_visibility, 'chicken-corn-rice-bowl', 'Chicken Corn Rice Bowl', 'A lime chicken, corn, and rice bowl.', 4, 35, array['dinner']::text[], array['Mexican-inspired']::text[], array['dairy-free']::text[], array['Thaw frozen chicken breast in the refrigerator before starting. Brown the chicken breast in vegetable oil with cumin and cook until it reaches 165°F.', 'Simmer the rice in the water until tender, warming the corn during the final five minutes; add the chicken and finish the bowls with lime.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-095', null::uuid, 'published'::public.recipe_visibility, 'chicken-spinach-rice', 'Chicken Spinach Rice', 'Chicken breast and spinach served with pantry rice.', 4, 35, array['dinner']::text[], array['Mediterranean-inspired']::text[], array['dairy-free']::text[], array['Thaw frozen chicken breast in the refrigerator before starting. Brown the chicken breast in olive oil with garlic and salt, then cook until it reaches 165°F.', 'Simmer the rice in the water until tender. Wilt the spinach in the chicken pan, then serve the chicken and spinach over the rice.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-096', null::uuid, 'published'::public.recipe_visibility, 'chicken-pepper-rice', 'Chicken Pepper Rice', 'A colorful chicken pepper rice bowl.', 4, 38, array['dinner']::text[], array['Asian-inspired']::text[], array['dairy-free']::text[], array['Thaw frozen chicken breast in the refrigerator before starting, then brown the chicken breast in vegetable oil and cook until it reaches 165°F.', 'Cook the bell pepper until tender-crisp and stir in the soy sauce. Simmer the rice in the water until tender and spoon the chicken and bell pepper over it.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-097', null::uuid, 'published'::public.recipe_visibility, 'chicken-thigh-potato-tray', 'Chicken Thigh Potato Tray', 'A reduced-ingredient chicken thigh and potato tray bake.', 4, 50, array['dinner']::text[], array['European-inspired']::text[], array['dairy-free']::text[], array['Thaw frozen chicken thighs in the refrigerator before starting. Heat the oven to 425°F; cut the potato into one-inch pieces and toss it with olive oil, paprika, salt, and black pepper.', 'Roast the potato for 15 minutes, add the chicken thighs, and continue roasting until the potato is tender and the chicken thighs reach 165°F.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-098', null::uuid, 'published'::public.recipe_visibility, 'chicken-thigh-green-bean-pan', 'Chicken Thigh Green Bean Pan', 'A one-pan chicken thigh and green bean dinner.', 4, 35, array['dinner']::text[], array['American']::text[], array['dairy-free']::text[], array['Thaw frozen chicken thighs in the refrigerator before starting. Brown the chicken thighs in olive oil, then cover and cook until they reach 165°F.', 'Add the green beans and cook until tender, then stir in the mustard and salt and coat the chicken and green beans before serving.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-099', null::uuid, 'published'::public.recipe_visibility, 'chicken-breast-tomato-pasta', 'Chicken Breast Tomato Pasta', 'Fast tomato pasta with fully cooked chicken breast.', 4, 30, array['dinner']::text[], array['Italian-inspired']::text[], array[]::text[], array['Thaw frozen chicken breast in the refrigerator before starting. Boil the dried pasta until al dente, reserving a little cooking water, and brown the chicken breast in olive oil until it reaches 165°F.', 'Warm the marinara sauce, toss it with the drained pasta and chicken breast, loosen with reserved pasta water if needed, and finish with parmesan cheese.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-100', null::uuid, 'published'::public.recipe_visibility, 'chicken-cabbage-noodles', 'Chicken Cabbage Noodles', 'Quick chicken and cabbage noodles for a weeknight.', 4, 28, array['dinner']::text[], array['Asian-inspired']::text[], array['dairy-free']::text[], array['Thaw frozen chicken breast in the refrigerator before starting. Boil the dried noodles until tender, then drain; brown the chicken breast in vegetable oil until it reaches 165°F.', 'Cook the cabbage in the chicken pan until tender, then toss in the noodles, soy sauce, and sesame oil and heat through.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-101', null::uuid, 'published'::public.recipe_visibility, 'peanut-butter-banana-oats', 'Peanut Butter Banana Oats', 'Creamy oats with banana and optional peanut butter.', 4, 10, array['breakfast']::text[], array['American']::text[], array['vegetarian']::text[], array['Simmer the oats and milk over medium-low heat until creamy, stirring often, then fold in the sliced banana and cinnamon.', 'Divide the oats into bowls, swirl in the peanut butter, and finish with honey before serving warm.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-102', null::uuid, 'published'::public.recipe_visibility, 'apple-cinnamon-oats', 'Apple Cinnamon Oats', 'Warm apple oats for a simple breakfast.', 4, 12, array['breakfast']::text[], array['American']::text[], array['vegetarian']::text[], array['Dice the apple and simmer it with the oats, milk, and cinnamon over medium-low heat until the apple and oats are tender.', 'Spoon the apple oats into bowls and finish each serving with maple syrup.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-103', null::uuid, 'published'::public.recipe_visibility, 'berry-yogurt-oats', 'Berry Yogurt Oats', 'No-cook yogurt oats with berries.', 4, 245, array['breakfast']::text[], array['European-inspired']::text[], array['vegetarian']::text[], array['Stir the oats and yogurt together until evenly moistened, then fold in the berries and cinnamon.', 'Cover and refrigerate for at least four hours so the oats soften, then stir well and finish with honey before serving.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-104', null::uuid, 'published'::public.recipe_visibility, 'banana-yogurt-bowl', 'Banana Yogurt Bowl', 'A fast banana yogurt bowl for breakfast or snack time.', 4, 5, array['breakfast', 'snack']::text[], array['Mediterranean-inspired']::text[], array['vegetarian']::text[], array['Slice the banana and fold it into the yogurt with the berries and cinnamon.', 'Divide the banana yogurt among bowls and drizzle each serving with honey.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-105', null::uuid, 'published'::public.recipe_visibility, 'apple-peanut-butter-toast', 'Apple Peanut Butter Toast', 'Crunchy apple toast with peanut butter.', 4, 8, array['breakfast', 'snack']::text[], array['American']::text[], array['vegetarian']::text[], array['Toast the bread until crisp and spread each slice with peanut butter.', 'Thinly slice the apple, layer it over the toast, and finish with cinnamon and honey.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-106', null::uuid, 'published'::public.recipe_visibility, 'tomato-egg-toast', 'Tomato Egg Toast', 'Egg and tomato toast that works for breakfast or lunch.', 4, 15, array['breakfast', 'lunch']::text[], array['Mediterranean-inspired']::text[], array['vegetarian']::text[], array['Toast the bread and slice the tomato. Heat the olive oil, add the eggs, season with salt and black pepper, and cook until the whites and yolks are fully set.', 'Layer the tomato and cooked eggs over the bread and serve immediately.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-107', null::uuid, 'published'::public.recipe_visibility, 'spinach-cheddar-eggs', 'Spinach Cheddar Eggs', 'Soft scrambled eggs with spinach and cheddar.', 4, 12, array['breakfast']::text[], array['American']::text[], array['vegetarian']::text[], array['Melt the butter in a skillet, add the spinach, and cook until wilted; season with salt and black pepper.', 'Add the eggs and stir until fully set, then fold in the cheddar cheese until melted.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-108', null::uuid, 'published'::public.recipe_visibility, 'salsa-egg-tortillas', 'Salsa Egg Tortillas', 'Breakfast tortillas with eggs and salsa.', 4, 15, array['breakfast', 'lunch']::text[], array['Mexican-inspired']::text[], array['vegetarian']::text[], array['Warm the tortillas. Scramble the eggs until fully set, then fold in the salsa and cheddar cheese until hot and melted.', 'Fill the tortillas with the egg mixture and finish with hot sauce.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-109', null::uuid, 'published'::public.recipe_visibility, 'mushroom-egg-skillet', 'Mushroom Egg Skillet', 'A quick mushroom and egg skillet.', 4, 15, array['breakfast', 'lunch']::text[], array['European-inspired']::text[], array['vegetarian']::text[], array['Melt the butter in a skillet and brown the mushrooms with thyme and salt until their moisture cooks away.', 'Add the eggs and stir gently until the eggs are fully set, then divide among plates.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-110', null::uuid, 'published'::public.recipe_visibility, 'potato-egg-hash', 'Potato Egg Hash', 'Crisp potato hash with eggs.', 4, 25, array['breakfast', 'lunch']::text[], array['American']::text[], array['vegetarian']::text[], array['Dice the potato and onion, then cook them in vegetable oil with paprika until the potato is tender and browned.', 'Add the eggs and stir until fully set, scraping the browned potato from the pan as the eggs cook.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-111', null::uuid, 'published'::public.recipe_visibility, 'tuna-cucumber-toast', 'Tuna Cucumber Toast', 'Cool tuna cucumber toast for lunch.', 4, 10, array['lunch']::text[], array['European-inspired']::text[], array[]::text[], array['Toast the bread. Mix the drained tuna with mayonnaise, lemon juice, black pepper, and diced cucumber.', 'Spoon the tuna and cucumber mixture over the toast and serve promptly.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-112', null::uuid, 'published'::public.recipe_visibility, 'white-bean-tomato-toast', 'White Bean Tomato Toast', 'A fiber-rich white bean and tomato toast.', 4, 10, array['lunch']::text[], array['Mediterranean-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Toast the bread and mash the white beans with olive oil, lemon juice, and salt.', 'Spread the white beans over the toast, top with sliced tomato, and serve.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-113', null::uuid, 'published'::public.recipe_visibility, 'avocado-black-bean-tortillas', 'Avocado Black Bean Tortillas', 'Fast black bean and avocado tortillas.', 4, 12, array['lunch']::text[], array['Mexican-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Warm the tortillas and black beans, then mash the avocado with lime juice and cumin.', 'Fill each tortilla with black beans, avocado, and salsa and fold before serving.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-114', null::uuid, 'published'::public.recipe_visibility, 'chickpea-cucumber-salad', 'Chickpea Cucumber Salad', 'A crisp chickpea cucumber salad.', 4, 10, array['lunch', 'side']::text[], array['Mediterranean-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Dice the cucumber and tomato, then combine them with the drained chickpeas.', 'Whisk the lemon juice with olive oil, toss it through the chickpea salad, and serve.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-115', null::uuid, 'published'::public.recipe_visibility, 'tuna-lettuce-cups', 'Tuna Lettuce Cups', 'Cool tuna-filled lettuce cups.', 4, 10, array['lunch']::text[], array['American']::text[], array[]::text[], array['Mix the drained tuna with mayonnaise, mustard, and diced cucumber.', 'Separate the lettuce into cups, spoon in the tuna mixture, and serve chilled.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-116', null::uuid, 'published'::public.recipe_visibility, 'cheddar-tomato-quesadillas', 'Cheddar Tomato Quesadillas', 'Crisp tomato and cheddar quesadillas.', 4, 12, array['lunch', 'snack']::text[], array['Mexican-inspired']::text[], array['vegetarian']::text[], array['Layer cheddar cheese and sliced tomato over half of each tortilla, fold, and brush the outsides lightly with vegetable oil.', 'Cook the tortillas in a skillet until crisp and the cheddar cheese melts, then cut into wedges and serve with salsa.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-117', null::uuid, 'published'::public.recipe_visibility, 'cucumber-yogurt-cups', 'Cucumber Yogurt Cups', 'Cool cucumber yogurt cups.', 4, 5, array['snack', 'side']::text[], array['Mediterranean-inspired']::text[], array['vegetarian']::text[], array['Dice the cucumber and fold it into the yogurt with lemon juice and black pepper.', 'Chill the cucumber yogurt briefly, then divide it among cups and serve cold.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-118', null::uuid, 'published'::public.recipe_visibility, 'cinnamon-banana-toast', 'Cinnamon Banana Toast', 'Warm banana toast with cinnamon.', 4, 8, array['breakfast', 'snack']::text[], array['American']::text[], array['vegetarian']::text[], array['Toast the bread and spread it with butter while warm.', 'Top the bread with sliced banana, then finish with cinnamon and honey.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-119', null::uuid, 'published'::public.recipe_visibility, 'salsa-bean-snack-cups', 'Salsa Bean Snack Cups', 'No-cook black bean salsa cups.', 4, 8, array['snack', 'side']::text[], array['Mexican-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Warm the black beans and corn, then cool them slightly and stir in the salsa.', 'Divide into cups, top with diced avocado, and squeeze lime over each serving.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-120', null::uuid, 'published'::public.recipe_visibility, 'apple-berry-yogurt', 'Apple Berry Yogurt', 'Fresh apple and berry yogurt.', 4, 5, array['breakfast', 'snack']::text[], array['European-inspired']::text[], array['vegetarian']::text[], array['Dice the apple and combine it with the berries and yogurt.', 'Divide the fruit yogurt among bowls and finish with honey and cinnamon.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-121', null::uuid, 'published'::public.recipe_visibility, 'cumin-black-bean-rice', 'Cumin Black Bean Rice', 'Simple cumin black beans over rice.', 4, 30, array['lunch', 'dinner']::text[], array['Mexican-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Simmer the rice in the water until tender. Warm the black beans in vegetable oil with cumin.', 'Fluff the rice, fold in the seasoned black beans, and top with salsa.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-122', null::uuid, 'published'::public.recipe_visibility, 'white-bean-spinach-rice', 'White Bean Spinach Rice', 'White beans and spinach with rice.', 4, 30, array['dinner']::text[], array['Mediterranean-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Simmer the rice in the water until tender. Warm the white beans in olive oil with garlic.', 'Wilt the spinach into the white beans, then spoon the mixture over the rice.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-123', null::uuid, 'published'::public.recipe_visibility, 'kidney-bean-tomato-rice', 'Kidney Bean Tomato Rice', 'Tomato kidney beans with rice.', 4, 35, array['dinner']::text[], array['Caribbean-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Simmer the rice in the water until tender. Warm the kidney beans and canned tomatoes with chili powder and vegetable oil.', 'Fluff the rice and serve the kidney bean mixture over it.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-124', null::uuid, 'published'::public.recipe_visibility, 'chickpea-curry-rice', 'Chickpea Curry Rice', 'A streamlined chickpea curry rice dinner.', 4, 35, array['dinner']::text[], array['South Asian-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Simmer the rice in the water until tender. Bloom the curry powder in vegetable oil, then add the chickpeas and coconut milk.', 'Simmer the chickpea curry until slightly thickened and serve it over the rice.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-125', null::uuid, 'published'::public.recipe_visibility, 'lentil-tomato-rice', 'Lentil Tomato Rice', 'A one-pot lentil tomato rice meal.', 4, 40, array['dinner']::text[], array['Middle Eastern-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Simmer the dried lentils in part of the water until nearly tender, then add the rice, remaining water, canned tomatoes, cumin, and vegetable oil.', 'Cover and cook until the lentils and rice are tender, adding a small splash of water only if the pan dries before they finish.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-126', null::uuid, 'published'::public.recipe_visibility, 'tofu-pea-rice-bowl', 'Tofu Pea Rice Bowl', 'Tofu and pea rice bowls.', 4, 30, array['dinner']::text[], array['Asian-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Simmer the rice in the water until tender, adding the peas for the final five minutes.', 'Brown the tofu in vegetable oil, add the soy sauce and sesame oil, and serve the tofu over the pea rice.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-127', null::uuid, 'published'::public.recipe_visibility, 'broccoli-cheddar-rice', 'Broccoli Cheddar Rice', 'Comforting broccoli cheddar rice.', 4, 30, array['dinner', 'side']::text[], array['American']::text[], array['vegetarian']::text[], array['Simmer the rice in the water until tender, steaming the broccoli above it or in a separate pan.', 'Fold the broccoli, butter, cheddar cheese, and black pepper into the hot rice until the cheese melts.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-128', null::uuid, 'published'::public.recipe_visibility, 'tomato-basil-rice', 'Tomato Basil Rice', 'Tomato basil rice for a side or light meal.', 4, 28, array['side', 'dinner']::text[], array['Italian-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Combine the rice, canned tomatoes, water, olive oil, and salt and bring to a simmer.', 'Cover and cook until the rice is tender, then fold in the basil and rest for five minutes before serving.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-129', null::uuid, 'published'::public.recipe_visibility, 'mushroom-thyme-rice', 'Mushroom Thyme Rice', 'Savory mushroom thyme rice.', 4, 30, array['dinner', 'side']::text[], array['European-inspired']::text[], array['vegetarian']::text[], array['Brown the mushrooms in butter with thyme and salt until their liquid cooks away.', 'Simmer the rice in the water until tender, then fold in the mushrooms and rest covered for five minutes.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-130', null::uuid, 'published'::public.recipe_visibility, 'corn-lime-rice', 'Corn Lime Rice', 'Bright corn lime rice.', 4, 25, array['side']::text[], array['Mexican-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Simmer the rice in the water until nearly tender, then fold in the corn and cumin and cook for five more minutes.', 'Rest the rice covered, then stir in the vegetable oil and lime juice before serving.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-131', null::uuid, 'published'::public.recipe_visibility, 'quinoa-chickpea-bowl', 'Quinoa Chickpea Bowl', 'A simple quinoa chickpea bowl.', 4, 25, array['lunch', 'dinner']::text[], array['Mediterranean-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Rinse the quinoa, then simmer it in the water until tender and drain the chickpeas.', 'Combine the quinoa and chickpeas with diced cucumber, lemon juice, and olive oil and serve warm or cool.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-132', null::uuid, 'published'::public.recipe_visibility, 'black-bean-quinoa', 'Black Bean Quinoa', 'Black beans and quinoa with salsa.', 4, 25, array['lunch', 'dinner']::text[], array['Mexican-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Rinse the quinoa, then simmer it in the water until tender; warm the black beans separately with cumin.', 'Combine the quinoa and black beans, then finish with salsa and lime juice.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-133', null::uuid, 'published'::public.recipe_visibility, 'lemon-pea-couscous', 'Lemon Pea Couscous', 'Fast lemon pea couscous.', 4, 15, array['lunch', 'side']::text[], array['North African-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Bring the water to a boil, pour it over the dried couscous, cover, and let stand until tender; warm the peas separately.', 'Fluff the couscous with olive oil and black pepper, fold in the peas, and finish with lemon juice.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-134', null::uuid, 'published'::public.recipe_visibility, 'chickpea-tomato-couscous', 'Chickpea Tomato Couscous', 'Chickpea tomato couscous.', 4, 18, array['lunch', 'dinner']::text[], array['North African-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Bring the water to a boil, pour it over the dried couscous, cover, and let stand until tender.', 'Fluff the couscous with olive oil and cumin, then fold in the chickpeas and diced tomato.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-135', null::uuid, 'published'::public.recipe_visibility, 'white-bean-pesto-pasta', 'White Bean Pesto Pasta', 'Quick pesto pasta with white beans.', 4, 20, array['dinner']::text[], array['Italian-inspired']::text[], array['vegetarian']::text[], array['Boil the dried pasta until al dente, adding the spinach for the final minute, then drain and reserve a little cooking water.', 'Warm the white beans, then toss them with the pasta, spinach, pesto, and parmesan cheese, loosening with reserved water if needed.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-136', null::uuid, 'published'::public.recipe_visibility, 'lentil-marinara-pasta', 'Lentil Marinara Pasta', 'Hearty lentil marinara pasta.', 4, 25, array['dinner']::text[], array['Italian-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Simmer the dried lentils in water until tender. Boil the dried pasta until al dente and drain.', 'Warm the marinara sauce with oregano and olive oil, then fold in the lentils and pasta and heat through.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-137', null::uuid, 'published'::public.recipe_visibility, 'tofu-cabbage-noodles', 'Tofu Cabbage Noodles', 'Tofu and cabbage noodles.', 4, 25, array['dinner']::text[], array['Asian-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Boil the dried noodles until tender and drain. Brown the tofu in vegetable oil, then add the cabbage and cook until tender.', 'Toss the noodles with the tofu, cabbage, soy sauce, and sesame oil and heat through.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-138', null::uuid, 'published'::public.recipe_visibility, 'peanut-broccoli-noodles', 'Peanut Broccoli Noodles', 'Creamy peanut broccoli noodles.', 4, 22, array['dinner']::text[], array['Southeast Asian-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Boil the dried noodles until tender, adding the broccoli for the final three minutes, then drain and reserve a quarter cup of cooking water.', 'Whisk the peanut butter with soy sauce, hot sauce, and the measured water, then toss the sauce with the noodles and broccoli.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-139', null::uuid, 'published'::public.recipe_visibility, 'black-bean-sweet-potato', 'Black Bean Sweet Potato', 'Roasted sweet potato with black beans.', 4, 35, array['dinner']::text[], array['Mexican-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Cut the sweet potato into one-inch pieces, toss with vegetable oil and cumin, and roast at 425°F until tender and browned.', 'Warm the black beans and salsa, then spoon them over the roasted sweet potato.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-140', null::uuid, 'published'::public.recipe_visibility, 'chickpea-spinach-skillet', 'Chickpea Spinach Skillet', 'A quick chickpea spinach tomato skillet.', 4, 20, array['dinner']::text[], array['Mediterranean-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Warm the chickpeas and canned tomatoes in olive oil with cumin until bubbling.', 'Add the spinach by handfuls and cook until wilted, then simmer briefly so the skillet thickens.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-141', null::uuid, 'published'::public.recipe_visibility, 'soy-salmon-rice', 'Soy Salmon Rice', 'Soy-glazed salmon with rice.', 4, 30, array['dinner']::text[], array['Japanese-inspired']::text[], array['dairy-free']::text[], array['Thaw frozen salmon in the refrigerator before starting. Simmer the rice in the water until tender.', 'Brush the salmon with soy sauce and cook until it reaches 145°F and flakes easily, then finish with sesame oil and serve with the rice.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-142', null::uuid, 'published'::public.recipe_visibility, 'lemon-salmon-potatoes', 'Lemon Salmon Potatoes', 'Lemon salmon and roasted potatoes.', 4, 45, array['dinner']::text[], array['European-inspired']::text[], array['dairy-free']::text[], array['Thaw frozen salmon in the refrigerator before starting. Heat the oven to 425°F, cut the potato into one-inch pieces, and toss with olive oil and salt; roast for 20 minutes.', 'Move the potato aside, add the salmon, and roast until the potato is tender and the salmon reaches 145°F and flakes easily, about 12 to 15 minutes; finish with lemon.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-143', null::uuid, 'published'::public.recipe_visibility, 'shrimp-corn-rice', 'Shrimp Corn Rice', 'Quick shrimp corn rice.', 4, 28, array['dinner']::text[], array['Latin American-inspired']::text[], array['dairy-free']::text[], array['Thaw frozen shrimp in the refrigerator before starting. Simmer the rice in the water until tender, adding the corn for the final five minutes.', 'Cook the shrimp in vegetable oil with cumin until opaque and they reach 145°F, then serve over the corn rice and finish with lime.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-144', null::uuid, 'published'::public.recipe_visibility, 'garlic-shrimp-pasta', 'Garlic Shrimp Pasta', 'Fast garlic shrimp pasta.', 4, 20, array['dinner']::text[], array['Italian-inspired']::text[], array['dairy-free']::text[], array['Thaw frozen shrimp in the refrigerator before starting. Boil the dried pasta until al dente, then drain and reserve a little cooking water.', 'Cook the shrimp in olive oil with garlic until opaque and they reach 145°F, then toss with the pasta and lemon juice, loosening with reserved water if needed.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-145', null::uuid, 'published'::public.recipe_visibility, 'quick-tuna-tomato-pasta', 'Quick Tuna Tomato Pasta', 'Pantry tuna tomato pasta.', 4, 20, array['dinner']::text[], array['Mediterranean-inspired']::text[], array['dairy-free']::text[], array['Boil the dried pasta until al dente, then drain and reserve a little cooking water.', 'Warm the tuna and canned tomatoes with oregano and olive oil, then toss with the pasta and loosen with reserved water if needed.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-146', null::uuid, 'published'::public.recipe_visibility, 'beef-pepper-rice', 'Beef Pepper Rice', 'Ground beef and pepper rice bowls.', 4, 30, array['dinner']::text[], array['Asian-inspired']::text[], array['dairy-free']::text[], array['Thaw frozen ground beef in the refrigerator before starting. Simmer the rice in the water until tender.', 'Cook the ground beef and bell pepper in vegetable oil until the beef reaches 160°F, then stir in the soy sauce and serve over the rice.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-147', null::uuid, 'published'::public.recipe_visibility, 'beef-tomato-rice', 'Beef Tomato Rice', 'Tomato beef over rice.', 4, 35, array['dinner']::text[], array['Mexican-inspired']::text[], array['dairy-free']::text[], array['Thaw frozen ground beef in the refrigerator before starting. Cook the ground beef in vegetable oil with chili powder until it reaches 160°F, then add the canned tomatoes.', 'Simmer the rice in the water until tender and serve the beef mixture over it.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-148', null::uuid, 'published'::public.recipe_visibility, 'sausage-cabbage-skillet', 'Sausage Cabbage Skillet', 'A simple sausage cabbage skillet.', 4, 25, array['dinner']::text[], array['European-inspired']::text[], array['dairy-free']::text[], array['Thaw frozen sausage in the refrigerator before starting. Brown the sausage in vegetable oil until it reaches 160°F.', 'Add the cabbage and black pepper and cook until tender, then stir in the mustard and serve.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-149', null::uuid, 'published'::public.recipe_visibility, 'sausage-tomato-pasta', 'Sausage Tomato Pasta', 'Sausage marinara pasta.', 4, 30, array['dinner']::text[], array['Italian-American']::text[], array[]::text[], array['Thaw frozen sausage in the refrigerator before starting. Boil the dried pasta until al dente and drain.', 'Cook the sausage until it reaches 160°F, add the marinara sauce and oregano, then toss with the pasta and finish with parmesan cheese.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-150', null::uuid, 'published'::public.recipe_visibility, 'pork-chop-apple-pan', 'Pork Chop Apple Pan', 'Pork chops with warm apples.', 4, 30, array['dinner']::text[], array['European-inspired']::text[], array['dairy-free']::text[], array['Thaw frozen pork chops in the refrigerator before starting. Brown the pork chops in olive oil with thyme and mustard.', 'Add the sliced apple and cook until tender and the pork chops reach 145°F; rest the pork chops for three minutes before serving.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-151', null::uuid, 'published'::public.recipe_visibility, 'pork-tenderloin-sweet-potato', 'Pork Tenderloin Sweet Potato', 'Paprika pork tenderloin with sweet potatoes.', 4, 40, array['dinner']::text[], array['American']::text[], array['dairy-free']::text[], array['Thaw frozen pork tenderloin in the refrigerator before starting. Heat the oven to 425°F and toss cubed sweet potato with olive oil, paprika, and salt.', 'Roast the sweet potato for 15 minutes, add the pork tenderloin, and continue until the sweet potato is tender and the pork reaches 145°F; rest the pork for three minutes before slicing.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-152', null::uuid, 'published'::public.recipe_visibility, 'bacon-pea-pasta', 'Bacon Pea Pasta', 'Bacon and pea pasta.', 4, 25, array['dinner']::text[], array['Italian-inspired']::text[], array[]::text[], array['Boil the dried pasta until al dente, adding the peas for the final two minutes, then drain and reserve a little cooking water.', 'Cook the bacon until crisp, then toss it and the rendered pan juices with the pasta, peas, parmesan cheese, and black pepper.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-153', null::uuid, 'published'::public.recipe_visibility, 'white-bean-kale-soup', 'White Bean Kale Soup', 'A quick white bean and kale soup.', 4, 25, array['lunch', 'dinner']::text[], array['Mediterranean-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Combine the white beans, vegetable broth, canned tomatoes, and thyme and bring to a simmer.', 'Add the kale and simmer until tender, then divide the soup among bowls.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-154', null::uuid, 'published'::public.recipe_visibility, 'cumin-lentil-carrot-soup', 'Cumin Lentil Carrot Soup', 'Warming lentil carrot soup.', 4, 35, array['lunch', 'dinner']::text[], array['Middle Eastern-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Cook the onion with cumin until softened, then add the dried lentils, carrot, and vegetable broth.', 'Simmer until the lentils and carrot are tender before serving.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-155', null::uuid, 'published'::public.recipe_visibility, 'chicken-rice-broth-bowl', 'Chicken Rice Broth Bowl', 'A streamlined chicken thigh and rice broth bowl.', 4, 35, array['lunch', 'dinner']::text[], array['American']::text[], array['dairy-free']::text[], array['Thaw frozen chicken thighs in the refrigerator before starting. Bring the chicken broth to a simmer with the carrot and thyme, then add the chicken thighs.', 'Cook the chicken thighs until they reach 165°F, remove and chop them, then add the rice and simmer until tender; return the chicken to the broth and heat through.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-156', null::uuid, 'published'::public.recipe_visibility, 'tomato-egg-rice', 'Tomato Egg Rice', 'Tomato eggs with rice.', 4, 25, array['lunch', 'dinner']::text[], array['Chinese-inspired']::text[], array['vegetarian', 'dairy-free']::text[], array['Simmer the rice in the water until tender. Heat the vegetable oil, add the canned tomatoes, and simmer until slightly thickened.', 'Stir in the eggs and soy sauce and cook until the eggs are fully set, then serve the eggs and canned tomatoes over the rice.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-157', null::uuid, 'published'::public.recipe_visibility, 'cauliflower-chickpea-tray', 'Cauliflower Chickpea Tray', 'Curry roasted cauliflower and chickpeas.', 4, 30, array['dinner', 'side']::text[], array['South Asian-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Heat the oven to 425°F and toss the cauliflower and chickpeas with vegetable oil, curry powder, and salt.', 'Roast until the cauliflower is tender and browned at the edges, stirring once halfway through.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-158', null::uuid, 'published'::public.recipe_visibility, 'roasted-green-beans-potatoes', 'Roasted Green Beans Potatoes', 'A practical roasted green bean and potato side.', 4, 35, array['side', 'dinner']::text[], array['European-inspired']::text[], array['vegan', 'vegetarian', 'dairy-free']::text[], array['Heat the oven to 425°F, cut the potato into one-inch pieces, and toss it with olive oil, garlic, and salt; roast for 15 minutes.', 'Add the green beans, toss, and continue roasting until the potato is tender and the green beans are browned.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-159', null::uuid, 'published'::public.recipe_visibility, 'cornmeal-cheddar-cakes', 'Cornmeal Cheddar Cakes', 'Savory cornmeal cheddar cakes.', 4, 25, array['breakfast', 'side']::text[], array['American']::text[], array['vegetarian']::text[], array['Whisk the eggs and milk, then stir in the cornmeal and cheddar cheese to make a thick batter.', 'Heat the vegetable oil in a skillet, spoon in small cakes, and cook on both sides until browned and the centers are fully set.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null),
  ('recipe-160', null::uuid, 'published'::public.recipe_visibility, 'baked-apple-oats', 'Baked Apple Oats', 'A warm baked apple oat breakfast.', 4, 35, array['breakfast']::text[], array['American']::text[], array['vegetarian']::text[], array['Heat the oven to 350°F. Whisk the eggs, milk, cinnamon, and maple syrup, then stir in the oats and diced apple.', 'Spread the oat mixture in a greased baking dish and bake until the center is set and the apple and oats are tender, about 30 minutes.']::text[], 'Foodtopia', 'Foodtopia Initial Catalog', null, null::date, 'seeded'::public.recipe_review_status, null)
on conflict (id) do update
set household_id = excluded.household_id,
    visibility = excluded.visibility,
    slug = excluded.slug,
    title = excluded.title,
    description = excluded.description,
    servings = excluded.servings,
    total_minutes = excluded.total_minutes,
    meal_types = excluded.meal_types,
    cuisines = excluded.cuisines,
    dietary_tags = excluded.dietary_tags,
    steps = excluded.steps,
    rights_owner = excluded.rights_owner,
    rights_author = excluded.rights_author,
    rights_reviewer = excluded.rights_reviewer,
    rights_reviewed_at = excluded.rights_reviewed_at,
    rights_status = excluded.rights_status,
    created_by = excluded.created_by
where (recipes.household_id, recipes.visibility, recipes.slug, recipes.title,
       recipes.description, recipes.servings, recipes.total_minutes, recipes.meal_types,
       recipes.cuisines, recipes.dietary_tags, recipes.steps, recipes.rights_owner,
       recipes.rights_author, recipes.rights_reviewer, recipes.rights_reviewed_at,
       recipes.rights_status, recipes.created_by)
  is distinct from
      (excluded.household_id, excluded.visibility, excluded.slug, excluded.title,
       excluded.description, excluded.servings, excluded.total_minutes, excluded.meal_types,
       excluded.cuisines, excluded.dietary_tags, excluded.steps, excluded.rights_owner,
       excluded.rights_author, excluded.rights_reviewer, excluded.rights_reviewed_at,
       excluded.rights_status, excluded.created_by);

